window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[94]={"id":"094","numero":94,"titre":"Rachialgie","objectifs":[{"id":"94-1","rang":"A","rubrique":"Définition","titre":"Connaître les définitions des rachialgies : cervicalgie, dorsalgie, lombalgie","contenu":"<p>La <span class=\"kw-def\">rachialgie</span> est un <strong>symptôme</strong> — une douleur du rachis — dont l'étiologie est extrêmement variée. La distinction fondamentale, à poser d'emblée, oppose :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Rachialgie commune</span></strong> — origine « dégénérative », liée à une <span class=\"kw-etio\">discopathie</span> et/ou une <span class=\"kw-etio\">atteinte articulaire postérieure</span>.</li>\n        <li><strong><span class=\"kw-def\">Rachialgie secondaire</span></strong> — nombreuses étiologies (<span class=\"kw-etio\">tumorale</span>, infectieuse, <span class=\"kw-etio\">inflammatoire</span>, fracturaire…), à éliminer avant de retenir une rachialgie commune.</li>\n      </ul>\n      <p>Devant une douleur associée d'un membre, distinguer une <span class=\"kw-clinique\">douleur radiculaire</span> (trajet nerveux précis) d'une simple <span class=\"kw-clinique\">douleur référée</span> (<span class=\"kw-clinique\">irradiation</span> à distance, sans caractéristique radiculaire).</p>\n      <table >\n        <thead><tr><th>Rachialgie</th><th>Définition topographique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Cervicalgie</span></td><td>Douleur du <strong>rachis cervical</strong>. Forme aiguë = <span class=\"kw-def\">torticolis</span> (syndrome douloureux cervical aigu avec <span class=\"kw-clinique\">contracture musculaire</span> associée).</td></tr>\n          <tr><td><span class=\"kw-def\">Dorsalgie</span></td><td>Douleur ressentie en regard du <strong>rachis thoracique</strong> (<span class=\"kw-chiffre\">T1 à T12</span>).</td></tr>\n          <tr><td><span class=\"kw-def\">Lombalgie</span></td><td>Douleur située entre la <strong>charnière thoracolombaire</strong> et le <strong>pli fessier inférieur</strong>.</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Lexique de la lombalgie</strong> — selon l'<span class=\"kw-clinique\">évolution</span> :</p>\n      <table >\n        <thead><tr><th>Terme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td>Lombalgie <strong>commune</strong></td><td>Non spécifique, en rapport avec une origine <span class=\"kw-etio\">discale</span>, <span class=\"kw-etio\">arthrosique</span> ou <span class=\"kw-etio\">musculaire</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Poussée</span> aiguë</strong> de lombalgie</td><td>Terme préférable à « lombalgie aiguë » — englobe <span class=\"kw-clinique\">les</span> douleurs aiguës avec ou sans fond douloureux préexistant.</td></tr>\n          <tr><td>Lombalgie <strong>chronique</strong></td><td><span class=\"kw-clinique\">Évolution</span> <span class=\"kw-chiffre\">&gt; 3 mois</span> (<span class=\"kw-chiffre\">~10 %</span> des cas).</td></tr>\n          <tr><td>Lombalgie <strong>récidivante</strong></td><td>Récidive dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 12 mois</span> — à considérer comme à risque de chronicité.</td></tr>\n          <tr><td>Lombalgie <strong>à risque de chronicité</strong></td><td>Caractérisée par la présence de <span class=\"kw-alerte\">drapeaux jaunes</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Devant toute rachialgie, il faut <strong>éliminer une rachialgie secondaire</strong> avant de retenir le diagnostic de rachialgie commune.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 95 — Radiculalgie - Syndrome canalaire</em></p>","frequence":1},{"id":"94-2","rang":"B","rubrique":"Épidémiologie","titre":"Connaître les prévalences des rachialgies : cervicalgie, dorsalgie, lombalgie","contenu":"<p><span class=\"kw-clinique\">Les</span> rachialgies sont parmi les motifs de consultation les plus fréquents. La <span class=\"kw-def\">prévalence</span> varie fortement selon le segment rachidien concerné.</p>\n      <table >\n        <thead><tr><th>Localisation</th><th><span class=\"kw-def\">Prévalence</span></th><th>Données clés</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Cervicalgie</span></td><td><span class=\"kw-chiffre\">~2/3</span> de la population au cours de la vie</td><td><span class=\"kw-def\">Incidence</span> annuelle <span class=\"kw-chiffre\">1,2 %</span> ; prédominance <strong>féminine</strong> (<span class=\"kw-chiffre\">2 F / 1 H</span>) ; ~<span class=\"kw-chiffre\">10 %</span> des actes de kinésithérapie sont cervicaux.</td></tr>\n          <tr><td><span class=\"kw-def\">Dorsalgie</span></td><td><span class=\"kw-chiffre\">10 à 20 %</span> — beaucoup plus rare</td><td>Prédominance <strong>féminine</strong> (<span class=\"kw-chiffre\">2 F / 1 H</span>) pour <span class=\"kw-clinique\">les</span> dorsalgies fonctionnelles.</td></tr>\n          <tr><td><span class=\"kw-def\">Lombalgie</span></td><td><span class=\"kw-chiffre\">1/4 à 1/3</span> de la population (<span class=\"kw-def\">prévalence</span> clinique ~<span class=\"kw-chiffre\">70 %</span>)</td><td>Pic à <span class=\"kw-chiffre\">50-65 ans</span> ; <strong>2ᵉ motif</strong> de consultation en médecine générale ; <span class=\"kw-def\">incidence</span> <span class=\"kw-chiffre\">60-90 %</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> La lombalgie est l'<strong>affection la plus invalidante au monde</strong> — <strong>1ʳᵉ cause</strong> d'années de vie vécues en situation de handicap, responsable d'environ <span class=\"kw-chiffre\">20 %</span> des arrêts de travail. <span class=\"kw-clinique\">Les</span> <span class=\"kw-chiffre\">10 %</span> de formes chroniques concentrent <span class=\"kw-chiffre\">80 %</span> des coûts.</div>","frequence":0},{"id":"94-3","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir interroger un patient et l’examiner devant une rachialgie","contenu":"<p>L'interrogatoire et l'examen visent à classer la douleur selon <span class=\"kw-clinique\">les</span> <strong>drapeaux</strong> : <span class=\"kw-clinique\">verts</span> (origine <strong>mécanique</strong>), <span class=\"kw-alerte\">jaunes et noirs</span> (risque de <strong>chronicité</strong>, cf. obj-7), <span class=\"kw-alerte\">rouges</span> (<strong>cause secondaire</strong>, cf. obj-6).</p>\n      <p><strong>Interrogatoire</strong> — caractériser la douleur :</p>\n      <ul>\n        <li><strong>Circonstances</strong> de survenue : effort, activité sportive ou professionnelle, traumatisme, posture prolongée — parfois sans cause retrouvée.</li>\n        <li><strong>Siège</strong> et <strong>irradiations</strong> : la lombalgie est typiquement <span class=\"kw-clinique\">lombaire basse</span>, le plus souvent <span class=\"kw-clinique\">lombofessière</span> ; <span class=\"kw-clinique\">les</span> irradiations peuvent être trompeuses.</li>\n        <li><strong>Rythme</strong> : <span class=\"kw-clinique\">mécanique</span> (diurne, aggravé par l'activité, soulagé par le repos) — un rythme <span class=\"kw-alerte\">inflammatoire</span> (nocturne, dérouillage matinal) est un signe d'alerte.</li>\n        <li><strong>Caractère impulsif</strong> à la <span class=\"kw-clinique\">toux</span>, la défécation, l'éternuement → oriente vers une <span class=\"kw-etio\">origine discale</span>.</li>\n        <li><strong>Mode évolutif</strong>, <strong>ATCD</strong> de rachialgies (épisodes antérieurs favorables = rassurants), recherche de <span class=\"kw-alerte\">signes généraux</span>.</li>\n      </ul>\n      <p><strong>Examen clinique</strong> — patient debout, examiné de profil et de dos :</p>\n      <ul>\n        <li><strong>Statique rachidienne</strong> : <span class=\"kw-clinique\">hyperlordose</span> lombaire, <span class=\"kw-clinique\">hypercyphose</span>, <span class=\"kw-clinique\">scoliose</span>, recherche d'une <span class=\"kw-clinique\">gibbosité</span> en antéflexion.</li>\n        <li><strong>Points douloureux</strong> à la palpation : processus épineux, espaces interépineux, muscles paravertébraux.</li>\n        <li><strong>Mobilités</strong> (flexion-extension, latéroflexions, rotations) : raideur en phase aiguë, mobilités subnormales dans la chronicité.</li>\n        <li><strong>Syndrome cellulo-myalgique</strong> : <span class=\"kw-clinique\">hyperesthésie</span> au <strong>palper-rouler</strong> → oriente vers une <span class=\"kw-etio\">arthrose des zygapophyses</span>.</li>\n        <li>Recherche d'une <strong>inégalité de longueur</strong> des membres inférieurs.</li>\n      </ul>\n      <p><strong>Examen neurologique</strong> — indispensable : il <strong>élimine une radiculalgie ou une atteinte de la queue de cheval</strong>.</p>\n      <table >\n        <thead><tr><th>Test</th><th>Principe</th><th>Intérêt</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Indice de Schöber</span></td><td>Repère à l'épineuse de <span class=\"kw-chiffre\">L5</span> + un second <span class=\"kw-chiffre\">10 cm au-dessus</span> ; mesure de l'allongement de la distance lors de la flexion antérieure du tronc. Selon la fiche source : normal si augmentation <span class=\"kw-chiffre\">&gt; 13 cm</span>, <span class=\"kw-alerte\">pathologique si &lt; 13 cm</span> (raideur rachidienne).</td><td><strong>Spécifique</strong> de la souplesse du rachis lombaire (charnière thoraco-lombaire).</td></tr>\n          <tr><td><span class=\"kw-def\">Distance main-sol</span></td><td>Mesure de la capacité à toucher le sol en flexion antérieure du tronc.</td><td>Test <strong>global</strong>, influencé par le rachis mais aussi <span class=\"kw-clinique\">les</span> hanches et les ischio-jambiers — <strong>non spécifique</strong>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le <span class=\"kw-def\">signe de Lasègue lombaire</span> (douleur lombaire pure, sans douleur radiculaire dans le membre inférieur) est possible et ne signe <strong>pas</strong> une atteinte radiculaire — contrairement au Lasègue radiculaire.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 95 — Radiculalgie - Syndrome canalaire</em></p>","frequence":4},{"id":"94-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principaux mécanismes à l’origine d’une rachialgie commune","contenu":"<p>La <span class=\"kw-def\">rachialgie commune</span> est d'origine <strong>dégénérative</strong>. Trois mécanismes — souvent intriqués chez un même patient — sont à connaître.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Substrat lésionnel</th><th>Profil clinique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Origine discale</span></td><td>Multifactorielle : fissure / arrachement de l'<span class=\"kw-def\">annulus fibrosus</span>, dégénérescence du <span class=\"kw-def\">nucleus pulposus</span>, protrusion discale, lésions l<span class=\"kw-chiffre\">iga</span>mentaires (<strong>ligament longitudinal postérieur</strong>, interépineux), lésions musculaires.</td><td>Tableau aigu (<span class=\"kw-def\">lumbago</span>, <span class=\"kw-def\">torticolis</span>) ou chronique ; douleur souvent <strong>médiane</strong>, <span class=\"kw-clinique\">impulsive à la toux</span>, avec <span class=\"kw-clinique\">syndrome rachidien</span> et <span class=\"kw-clinique\">signe de la sonnette</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Origine arthrosique</span></td><td>Associe <span class=\"kw-def\">discarthrose</span> et <span class=\"kw-def\">arthrose des zygapophyses</span> ; au rachis <strong>cervical</strong> s'ajoute l'<span class=\"kw-def\">uncarthrose</span> (l'uncus n'existe pas en lombaire).</td><td>Tableau plus <strong>torpide</strong>, sujet plus âgé ; douleur améliorée par l'<strong>antéflexion</strong>, syndrome <span class=\"kw-clinique\">cellulo-myalgique</span> au palper-rouler.</td></tr>\n          <tr><td><span class=\"kw-etio\">Origine musculaire</span></td><td>Douleurs des muscles <strong>paravertébraux</strong>.</td><td>Résulte d'une <strong>perte de fonction</strong> : muscles contractés en permanence, ne se relâchant plus — entretenue par le comportement du patient.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> La <strong>composante psycho-sociale et comportementale</strong> (<span class=\"kw-def\">kinésiophobie</span>, <span class=\"kw-def\">syndrome anxio-dépressif</span>, fausses croyances sur la « fragilité » du dos) favorise le <strong>maintien</strong> des douleurs et leur chronicisation. Il existe une <span class=\"kw-alerte\">mauvaise corrélation</span> entre anomalies radiographiques et clinique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 129 — Arthrose</em></p>","frequence":2},{"id":"94-5","rang":"B","rubrique":"Épidémiologie","titre":"Connaître les facteurs de risque de rachialgie","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">facteurs de risque</span> sont en partie communs aux trois segments rachidiens, en partie spécifiques d'une localisation.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th><span class=\"kw-def\">Facteurs de risque</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Communs</strong></td><td><span class=\"kw-etio\">Traumatismes</span> et <span class=\"kw-etio\">microtraumatismes répétés</span> ; <span class=\"kw-etio\">troubles de la statique rachidienne</span> ; <span class=\"kw-etio\">génétique</span> (ATCD familiaux) ; <span class=\"kw-etio\">sédentarité</span> ; <span class=\"kw-etio\">tabagisme</span>.</td></tr>\n          <tr><td><strong>Spécifiques lombalgie</strong></td><td><span class=\"kw-etio\">Surpoids</span> ; activités professionnelles à risque (<strong>port de charges</strong>, <strong>vibrations</strong> répétées — marteau-piqueur, stress professionnel) ; <span class=\"kw-etio\">maladie de Scheuermann</span>.</td></tr>\n          <tr><td><strong>Spécifiques cervicalgie</strong></td><td>Activités sportives, de loisir ou professionnelles avec <strong>postures prolongées</strong> ; cervicalgies sur écran ou téléphone portable (« <span class=\"kw-def\">text-neck</span> »).</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"94-6","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir demander à bon escient une imagerie devant une rachialgie","contenu":"<p>L'imagerie d'une rachialgie répond à des indications précises selon la <strong>localisation</strong>, la <strong>durée</strong> et la <strong>réponse au traitement</strong>. En dehors des <span class=\"kw-alerte\">drapeaux rouges</span>, elle n'est <strong>jamais systématique en phase aiguë</strong>.</p>\n      <table >\n        <thead><tr><th>Type de douleur</th><th>Critère d'imagerie</th><th>1ʳᵉ intention</th><th>2ᵉ intention</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Cervicalgie</span></td><td>Persistance <span class=\"kw-chiffre\">&gt; 4-6 semaines</span> sous traitement (pas d'imagerie pour un simple torticolis ni une cervicalgie connue récidivante)</td><td><span class=\"kw-imagerie\">Radiographie cervicale</span> F + P + ¾ ; cliché <span class=\"kw-imagerie\">C1-C2</span> de face si douleurs hautes ; clichés dynamiques si ATCD traumatiques</td><td><span class=\"kw-imagerie\">IRM</span> si échec radio ou suspicion de <span class=\"kw-alerte\">drapeaux rouges</span> ; <span class=\"kw-imagerie\">scintigraphie</span> si douleurs diffuses</td></tr>\n          <tr><td><span class=\"kw-def\">Dorsalgie</span></td><td><strong>Imagerie systématique</strong> (une cause sous-jacente est souvent recherchée)</td><td><span class=\"kw-imagerie\">Radiographie thoracique</span> F + P debout</td><td>Examen orienté selon la clinique (<span class=\"kw-imagerie\">RXT</span>, <span class=\"kw-imagerie\">EOGD</span>…)</td></tr>\n          <tr><td><span class=\"kw-def\">Lombalgie</span></td><td>Persistance <span class=\"kw-chiffre\">&gt; 6-8 semaines</span> sous traitement (pas d'imagerie pour un simple lumbago)</td><td><span class=\"kw-imagerie\">Radiographie lombaire</span> F + P debout ; bassin de face ; clichés dynamiques si ATCD traumatiques</td><td><span class=\"kw-imagerie\">IRM</span> si lombalgie chronique <span class=\"kw-chiffre\">&gt; 3 mois</span> ou <span class=\"kw-alerte\">drapeaux rouges</span></td></tr>\n          <tr><td><span class=\"kw-def\">Lombosciatique</span></td><td>Persistance <span class=\"kw-chiffre\">&gt; 8 semaines</span> malgré traitement bien conduit, ou douleur invalidante, ou <span class=\"kw-ttt\">chirurgie</span> / <span class=\"kw-bio\">infiltration</span> prévue, ou patient adolescent ou <span class=\"kw-chiffre\">&gt; 65 ans</span></td><td><span class=\"kw-imagerie\">IRM</span> +++ à privilégier ; <span class=\"kw-imagerie\">scanner</span> possible ; <span class=\"kw-imagerie\">radiographie</span> parfois utile</td><td><span class=\"kw-imagerie\">IRM</span> d'office si suspicion de <span class=\"kw-alerte\">drapeau rouge</span></td></tr>\n          <tr><td><span class=\"kw-def\">Névralgie cervico-brachiale</span></td><td>Persistance <span class=\"kw-chiffre\">&gt; 4-6 semaines</span> sous traitement</td><td><span class=\"kw-imagerie\">IRM</span> directement ; <span class=\"kw-imagerie\">scanner</span> moins performant ; <span class=\"kw-imagerie\">radiographie</span> parfois utile</td><td><span class=\"kw-imagerie\">IRM</span> si résistance au traitement ou <span class=\"kw-alerte\">drapeaux rouges</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Hiérarchie des modalités</strong> :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">IRM</span> — examen de <strong>référence</strong> en cas de suspicion neurologique ou de résistance au traitement.</li>\n        <li><span class=\"kw-imagerie\">Radiographie</span> — utile pour <span class=\"kw-clinique\">les</span> déformations et la <strong>statique rachidienne</strong>.</li>\n        <li><span class=\"kw-imagerie\">TDM</span> — moins performante, utilisée en <span class=\"kw-bio\">complément</span> de l'<span class=\"kw-imagerie\">IRM</span>.</li>\n        <li><span class=\"kw-alerte\">Drapeaux rouges</span> → <strong><span class=\"kw-imagerie\">IRM</span> en <span class=\"kw-alerte\">urgence</span></strong>.</li>\n      </ul>\n      <p>La <span class=\"kw-def\">classification de Modic</span> décrit <span class=\"kw-clinique\">les</span> modifications des plateaux vertébraux visibles en <span class=\"kw-imagerie\">IRM</span> au cours de la dégénérescence discale lombaire :</p>\n      <table >\n        <thead><tr><th>Modic</th><th>Définition</th><th>T1</th><th>T2</th><th>STIR</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Modic 1</strong></td><td><span class=\"kw-def\">Œdème</span> des plateaux vertébraux (<strong>douloureux</strong>)</td><td>Hypo</td><td>Hyper</td><td>Hyper</td></tr>\n          <tr><td><strong>Modic 2</strong></td><td><span class=\"kw-def\">Involution graisseuse</span></td><td>Hyper</td><td>Hyper</td><td>Hypo</td></tr>\n          <tr><td><strong>Modic 3</strong></td><td><span class=\"kw-def\">Ostéosclérose</span></td><td>Hypo</td><td>Hypo</td><td>—</td></tr>\n        </tbody>\n      </table>\n      <p>Le <span class=\"kw-alerte\">Modic 1</span> est corrélé à l'acutisation d'une lombalgie chronique et peut révéler une discopathie destructrice rapide.</p>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Il n'existe <strong>aucun parallélisme</strong> entre imagerie et clinique — un rachis très dégénératif peut être asymptomatique. L'imagerie a aussi un <span class=\"kw-alerte\">effet nocebo</span>. Pas d'indication à <strong>renouveler</strong> un examen en l'absence de modification des symptômes.</div>","frequence":8,"liens":[{"href":"https://radiopaedia.org/cases/normal-mri-lumbosacral-spine","label":"Radiopaedia : Normal MRI lumbosacral spine"},{"href":"https://radiopaedia.org/cases/normal-lumbar-spine-radiographs-annotated","label":"Radiopaedia : Normal lumbar spine radiographs"},{"href":"https://radiopaedia.org/cases/normal-lumbar-spine-ct","label":"Radiopaedia : Normal lumbar spine CT"},{"href":"https://radiopaedia.org/articles/modic-type-endplate-changes","label":"Radiopaedia : Modic type endplate changes"},{"href":"https://radiopaedia.org/articles/annular-fissure","label":"Radiopaedia : Annular fissure"},{"href":"https://radiopaedia.org/articles/spondylolisthesis-1","label":"Radiopaedia : Spondylolisthesis"},{"href":"https://radiopaedia.org/articles/degenerated-disc-1","label":"Radiopaedia : Degenerated disc"},{"href":"https://radiopaedia.org/articles/disc-protrusion","label":"Radiopaedia : Disc protrusion"},{"href":"https://radiopaedia.org/articles/retrolisthesis","label":"Radiopaedia : Retrolisthesis"},{"href":"https://radiopaedia.org/cases/normal-thoracic-spine-mri-2","label":"Radiopaedia : Normal thoracic spine MRI"},{"href":"https://radiopaedia.org/cases/normal-radiographic-anatomy-of-the-thoracic-spine","label":"Radiopaedia : Normal thoracic spine radiographs"},{"href":"https://radiopaedia.org/cases/normal-cervical-spine-ct","label":"Radiopaedia : Normal cervical spine CT"},{"href":"https://radiopaedia.org/cases/normal-cervical-spine-radiographs","label":"Radiopaedia : Normal cervical spine radiographs"},{"href":"https://radiopaedia.org/cases/normal-mri-cervical-spine-1","label":"Radiopaedia : Normal cervical spine MRI"},{"href":"https://radiopaedia.org/cases/cervical-disc-herniation","label":"Radiopaedia : Cervical disc herniation"},{"href":"https://radiopaedia.org/articles/cervical-canal-stenosis","label":"Radiopaedia : Cervical canal stenosis"},{"href":"https://radiopaedia.org/cases/cervical-spondylosis-1","label":"Radiopaedia : Cervical spondylosis"}]},{"id":"94-7","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les arguments en faveur d’une rachialgie secondaire conduisant à la pratique d’examens complémentaires (IRM)","contenu":"<div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\">drapeaux rouges</span> sont des <strong><span class=\"kw-alerte\">signes d'alarme</span> à rechercher systématiquement</strong> devant toute rachialgie. Leur présence fait craindre une <span class=\"kw-alerte\">cause secondaire</span> et conduit à des examens complémentaires — au premier rang desquels l'<span class=\"kw-imagerie\">IRM</span>.</div>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Arguments en faveur d'une rachialgie secondaire</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td>Âge d'apparition <span class=\"kw-chiffre\">&lt; 20 ans</span> ou <span class=\"kw-chiffre\">&gt; 55 ans</span> ; ATCD <span class=\"kw-etio\">tumoraux</span>, <span class=\"kw-etio\">infectieux</span> ou de maladie <span class=\"kw-etio\">inflammatoire</span> rhumatismale ; <span class=\"kw-etio\">immunosuppression</span>, toxicomanie, <span class=\"kw-ttt\">corticothérapie</span> prolongée.</td></tr>\n          <tr><td><strong>Caractéristiques de la douleur</strong></td><td>Début <span class=\"kw-alerte\">insidieux</span>, <span class=\"kw-clinique\">évolution</span> <strong>progressivement croissante</strong> ; douleurs <span class=\"kw-alerte\">nocturnes inflammatoires</span> (insomniantes), douleur de repos ; caractère <strong>rebelle</strong> aux traitements symptomatiques ; localisations multiples ou atypiques.</td></tr>\n          <tr><td><strong>Signes associés</strong></td><td><span class=\"kw-clinique\">Fièvre</span>, <span class=\"kw-clinique\">altération de l'état général</span>, <span class=\"kw-clinique\"><span class=\"kw-clinique\">sueurs</span> nocturnes</span>, <span class=\"kw-alerte\">perte de poids inexpliquée</span> ; <span class=\"kw-clinique\">adénopathies</span> ; déformation structurale importante de la colonne ; <span class=\"kw-clinique\">douleur thoracique</span> (rachialgies dorsales).</td></tr>\n          <tr><td><strong>Déficit neurologique</strong></td><td>Atteinte <span class=\"kw-alerte\">radiculaire</span> (<span class=\"kw-clinique\">déficit moteur</span> radiculaire ± névralgie cervico-brachiale) ; atteinte <span class=\"kw-alerte\">médullaire</span> (<span class=\"kw-clinique\">déficit moteur</span>/sensitif sous-lésionnel, signes d'irritation pyramidale, troubles vésicosphinctériens).</td></tr>\n          <tr><td><strong>Contexte traumatique ou chirurgical</strong></td><td>Traumatisme important (chute de hauteur) ; ATCD de <span class=\"kw-ttt\">chirurgie</span> du rachis avec modification de la symptomatologie.</td></tr>\n          <tr><td><strong>Suspicion de cancer</strong></td><td>ATCD de cancer, <span class=\"kw-clinique\">altération de l'état général</span>, <span class=\"kw-clinique\">perte de poids</span> inexpliquée.</td></tr>\n          <tr><td><strong>Infection disco-vertébrale</strong></td><td><span class=\"kw-clinique\">Fièvre</span> inexpliquée ; usage de drogues IV, contexte d'immunosuppression, <span class=\"kw-clinique\">bactériémie</span> récente.</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Dissection</span> artérielle</strong></td><td>Cervicalgies inhabituelles et persistantes + <span class=\"kw-clinique\">céphalées</span> inhabituelles + signes neurologiques focaux ; ATCD de maladie prédisposante (<span class=\"kw-etio\">Ehlers-Danlos</span>, <span class=\"kw-etio\">Marfan</span>, ostéogenèse imparfaite, dysplasie fibromusculaire).</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Affirmer qu'une <span class=\"kw-clinique\">radiculalgie</span> est <strong>à elle seule</strong> en faveur d'une rachialgie secondaire est <span class=\"kw-alerte\">FAUX</span> : il faut un <strong>déficit neurologique associé</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 93 — Compression médullaire non trauma</em></p>","frequence":7},{"id":"94-8","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les facteurs favorisants d’une évolution vers la chronicité d’une rachialgie","contenu":"<p>Moins de <span class=\"kw-chiffre\">10 %</span> des lombalgies aiguës évoluent vers la chronicité, mais cette <span class=\"kw-clinique\">évolution</span> est favorisée par des facteurs <strong>biopsychosociaux</strong> et <strong>professionnels</strong> — <span class=\"kw-clinique\">les</span> drapeaux jaunes et noirs.</p>\n      <p><strong>Drapeaux jaunes — contexte biopsychosocial :</strong></p>\n      <ul>\n        <li><span class=\"kw-alerte\">Dépression</span>, <span class=\"kw-alerte\">détresse</span> affective, anxiété, <strong>peur de la douleur</strong> et du traumatisme, <span class=\"kw-alerte\">catastrophisme</span>.</li>\n        <li>Conflit familial.</li>\n        <li>Fausses croyances et fausses informations quant à l'<span class=\"kw-clinique\">évolution</span>.</li>\n        <li>Comportements douloureux inappropriés : <strong>évitement</strong> ou <span class=\"kw-ttt\">réduction</span> de l'activité liés à la peur (questionnaire <span class=\"kw-def\">FABQ</span>).</li>\n      </ul>\n      <p><strong>Drapeaux noirs — facteurs professionnels :</strong></p>\n      <ul>\n        <li>Conflit professionnel ; excès de sollicitude (famille, médecins).</li>\n        <li><span class=\"kw-alerte\">Arrêts de travail prolongés</span> (<span class=\"kw-chiffre\">&gt; 4 semaines</span>), recherche de bénéfices secondaires.</li>\n        <li>Insatisfaction et conditions de travail difficiles sans opportunité de changement.</li>\n        <li>Conflits et litiges avec une assurance, la Sécurité sociale ou un expert.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-def\">Pronostic</span> fonctionnel.</strong> Après <span class=\"kw-chiffre\">6 mois</span> d'arrêt de travail pour lombalgie, la probabilité de reprise du travail est d'environ <span class=\"kw-chiffre\">50 %</span> ; après <span class=\"kw-chiffre\">1 an</span>, <span class=\"kw-chiffre\">25 %</span> ; après <span class=\"kw-chiffre\">2 ans</span>, quasi nulle. D'où l'enjeu d'une prise en charge <strong>précoce</strong>.</div>","frequence":3},{"id":"94-9","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies d’une rachialgie secondaire","contenu":"<p>Une rachialgie <span class=\"kw-def\">secondaire</span> relève d'une pathologie non mécanique. Quatre grands cadres étiologiques sont à connaître en priorité.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Tumorale</span></td><td><strong>Métastases</strong> osseuses (surtout lytiques) ; localisation <strong>myélomateuse</strong> ; tumeur primitive vertébrale.</td></tr>\n          <tr><td><span class=\"kw-etio\">Infectieuse</span></td><td><span class=\"kw-def\">Spondylodiscite</span> (spondylite plus rare).</td></tr>\n          <tr><td><span class=\"kw-etio\">Inflammatoire</span></td><td><span class=\"kw-def\">Spondyloarthrite</span>, rhumatisme psoriasique ; <span class=\"kw-def\">polyarthrite rhumatoïde</span> (atteinte <span class=\"kw-chiffre\">C1-C2</span>) ; chondrocalcinose ; rhumatisme à apatite.</td></tr>\n          <tr><td><span class=\"kw-etio\">Osseuse fragilisante</span></td><td><strong>Fracture vertébrale ostéoporotique</strong> (contexte de fragilité osseuse).</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Devant tout argument de rachialgie secondaire, l'<span class=\"kw-imagerie\">IRM</span> et un bilan <span class=\"kw-ttt\">biologique</span> (<span class=\"kw-bio\">CRP</span> / <span class=\"kw-bio\">VS</span>, <span class=\"kw-bio\">électrophorèse des protides</span>, <span class=\"kw-bio\">calcémie</span>) sont justifiés.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 156 — Infection ostéo-articulaire · 197 — Spondylarthrite <span class=\"kw-etio\">inflammatoire</span> · 307 — Tumeur osseuse · 320 — Myélome multiple des os · 128 — Ostéopathie fragilisante</em></p>","frequence":3},{"id":"94-10","rang":"B","rubrique":"Étiologies","titre":"Connaître les autres étiologies d’une rachialgie secondaire","contenu":"<p>Au-delà des étiologies principales, d'autres causes plus rares de rachialgie secondaire sont à connaître.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Neurologique</span></td><td>Tumeur <strong>intrarachidienne</strong> : <span class=\"kw-def\">neurinome</span>, <span class=\"kw-def\">méningiome</span> (bénins) ; <span class=\"kw-def\">épendymome</span>, <span class=\"kw-def\">astrocytome</span> (plus rares, graves) ; tumeur de la fosse postérieure.</td></tr>\n          <tr><td><span class=\"kw-etio\">Tumeur osseuse primitive bénigne</span></td><td><span class=\"kw-def\">Ostéoblastome</span>, <span class=\"kw-def\">angiome vertébral</span> (fréquent, souvent rassurant en <span class=\"kw-imagerie\">IRM</span>), <span class=\"kw-def\">ostéome ostéoïde</span>, tumeur à cellules géantes, kyste anévrismal, granulome <span class=\"kw-bio\">éosinophile</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Calcifications discales</span></td><td>Peuvent aboutir à une <span class=\"kw-def\">spondylodiscite microcristalline</span> : apatite carbonatée (nucléaire), pyrophosphate (chondrocalcinose), dépôts uratiques (rares).</td></tr>\n          <tr><td><span class=\"kw-etio\">Maladie de Paget</span></td><td>Atteinte radiologique caractéristique.</td></tr>\n          <tr><td><span class=\"kw-etio\">Post-traumatique</span></td><td>Fractures et luxations vertébrales.</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 93 — Compression médullaire non trauma</em></p>","frequence":0},{"id":"94-11","rang":"B","rubrique":"Étiologies","titre":"Connaître les étiologies d’une rachialgie compliquée","contenu":"<p>Une rachialgie <span class=\"kw-def\">compliquée</span> est une rachialgie associée à une <strong>complication neurologique</strong>. La gravité potentielle d'une rachialgie est la <span class=\"kw-alerte\">compression neurologique</span> : <strong>lente</strong> dans <span class=\"kw-clinique\">les</span> formes mécaniques, possiblement <strong>rapide</strong> et de présentation trompeuse dans les formes secondaires.</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Radiculaire</span></td><td><span class=\"kw-def\">Névralgie cervico-brachiale</span> (rachis cervical) ; <span class=\"kw-def\">lombosciatique</span> / <span class=\"kw-def\">lombocruralgie</span> (rachis lombaire) — principale complication de l'origine <span class=\"kw-etio\">discale</span>.</td></tr>\n          <tr><td><span class=\"kw-alerte\">Médullaire</span></td><td><span class=\"kw-def\">Compression médullaire lente</span> ; <span class=\"kw-def\">canal rachidien rétréci</span> avec <span class=\"kw-clinique\">claudication</span> d'origine radiculaire ou médullaire — principale complication de l'origine <span class=\"kw-etio\">arthrosique</span> ; myélopathie cervicarthrosique.</td></tr>\n          <tr><td><span class=\"kw-alerte\">Syndrome de la queue de cheval</span></td><td>Complication <strong>très rare mais grave</strong> d'une hernie discale lombaire.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Un déficit neurologique, des troubles vésicosphinctériens ou une <span class=\"kw-alerte\">anesthésie en selle</span> imposent une <span class=\"kw-imagerie\">IRM en urgence</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 93 — Compression médullaire non trauma · 95 — Radiculalgie - Syndrome canalaire</em></p>","frequence":1},{"id":"94-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les grands principes de prise en charge d’un sujet souffrant d’une rachialgie aiguë ou chronique","contenu":"<p>La prise en charge d'une rachialgie commune repose sur des <strong>principes généraux</strong> stables, qu'elle soit aiguë ou chronique.</p>\n      <ul>\n        <li><strong>Pas d'indication chirurgicale</strong> pour une rachialgie commune — <span class=\"kw-alerte\">même en présence d'une hernie discale</span> à l'imagerie.</li>\n        <li><strong>Ne pas traiter une image</strong> mais la <strong>symptomatologie</strong> du patient.</li>\n        <li><strong>Identifier l'origine</strong> de la rachialgie (discale, arthrosique, musculaire) pour orienter le traitement.</li>\n        <li>Se <strong>méfier de l'escalade thérapeutique</strong> : <span class=\"kw-ci\">corticothérapie</span> banalisée alors qu'elle est inefficace, <span class=\"kw-ci\">opioïdes forts</span> avec risque de dépendance.</li>\n        <li>Prise en charge <strong>active et précoce</strong>, intégrant le contexte <strong>socioprofessionnel et psychologique</strong>, pour éviter le passage à la chronicité.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> <span class=\"kw-alerte\">Proscrire l'alitement</span> et l'immobilisation prolongée. Conseiller au patient de <strong>rester actif</strong> et de poursuivre ses activités quotidiennes et professionnelles si l'intensité de la douleur le permet.</div>\n      <p><strong>Prise en charge pluridisciplinaire</strong> — <span class=\"kw-clinique\">les</span> intervenants selon la ligne :</p>\n      <table >\n        <thead><tr><th>Intervenant</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Médecin généraliste</strong></td><td>1ʳᵉ ligne — rachialgies sans signe d'alerte ni de gravité.</td></tr>\n          <tr><td><strong>Rhumatologue</strong></td><td>2ᵉ ligne — diagnostique, pour <span class=\"kw-clinique\">les</span> formes rebelles.</td></tr>\n          <tr><td><strong>Imageur</strong></td><td>3ᵉ ligne — formes rebelles, avec signes d'alerte ou de gravité.</td></tr>\n          <tr><td><strong>Rééducateur + kinésithérapeutes</strong></td><td>Formes rebelles ou en voie de chronicisation.</td></tr>\n          <tr><td><strong>Chirurgien</strong></td><td>Complications neurologiques, résistance au traitement médical.</td></tr>\n        </tbody>\n      </table>\n      <p>Dans <span class=\"kw-clinique\">les</span> formes chroniques, le <span class=\"kw-def\">programme de restauration fonctionnelle du rachis</span> se déroule en <strong><span class=\"kw-alerte\">hospitalisation</span></strong>, de façon multidisciplinaire (médecins MPR ou rhumatologue, kinésithérapeutes, ergothérapeutes, psychologues, assistants sociaux, diététiciens). Il vise le <strong>reconditionnement à l'effort</strong>, l'<span class=\"kw-def\">éducation thérapeutique</span> et la <strong>réinsertion socioprofessionnelle</strong>. Le bilan pré-rééducation comporte la mesure de la <span class=\"kw-clinique\">distance talon-fesse</span> et des <span class=\"kw-clinique\">angles poplités</span>, l'<span class=\"kw-def\">indice de Schöber</span>, le <span class=\"kw-def\">score</span> <span class=\"kw-def\">HAD</span> (anxiété-<span class=\"kw-def\">dépression</span>), le questionnaire <span class=\"kw-def\">FABQ</span> et un test de lever de charge (test de <span class=\"kw-def\">Pile</span>).</p>","frequence":6},{"id":"94-13","rang":"B","rubrique":"Prise en charge","titre":"Savoir quels traitements prescrire à un sujet souffrant d’une rachialgie aiguë ou rachialgie chronique. Avoir une vision rigoureuse de l’efficacité ou de l’inefficacité des nombreux traitements qui peuvent être proposés","contenu":"<p>L'objectif insiste sur une <strong>vision rigoureuse de l'efficacité et de l'inefficacité</strong> des traitements : beaucoup de traitements largement prescrits n'ont pas fait la preuve de leur efficacité.</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Cervicalgie commune aiguë</th><th>Lombalgie commune aiguë</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Médicamenteux</span></strong></td><td><span class=\"kw-ttt\">AINS</span> et <span class=\"kw-ttt\">antalgiques</span>.</td><td><span class=\"kw-ttt\">AINS</span> en 1ʳᵉ intention ; <span class=\"kw-ttt\">antalgiques de palier 2</span> possibles ; <span class=\"kw-ttt\">paracétamol</span> n'est plus recommandé sauf ponctuellement, à visée symptomatique.</td></tr>\n          <tr><td><strong>Immobilisation</strong></td><td>Éviter le <span class=\"kw-ci\">collier cervical</span> (peut aggraver la douleur) ; si nécessaire, <strong>minerve souple</strong> de durée brève (<span class=\"kw-chiffre\">2-3 jours</span>).</td><td><span class=\"kw-ttt\">Corset lombaire</span> <span class=\"kw-ttt\">antalgique</span> envisageable ; <span class=\"kw-ci\">proscrire l'alitement systématique</span> ; rester actif.</td></tr>\n          <tr><td><strong>Kinésithérapie / ostéopathie</strong></td><td>Action <strong>très limitée</strong> en phase aiguë ; <span class=\"kw-alerte\">manipulation cervicale</span> seulement après enquête diagnostique exhaustive (au minimum RX du rachis cervical) — risque de <span class=\"kw-alerte\">dissection artérielle post-manipulation</span>.</td><td>Séances utiles surtout chez <span class=\"kw-clinique\">les</span> patients à risque de chronicité ; manipulations <span class=\"kw-ci\">contre-indiquées</span> en cas de signes de souffrance nerveuse.</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Inefficace ou <span class=\"kw-ci\">à proscrire</span></strong> — à connaître pour l'EDN :</p>\n      <ul>\n        <li><span class=\"kw-ci\">Décontracturants / myorelaxants</span> : non validés (balance bénéfice-risque défavorable).</li>\n        <li><span class=\"kw-ci\">Corticoïdes par voie générale</span> : inefficaces.</li>\n        <li><span class=\"kw-ci\">Néfopam</span> : inefficace.</li>\n        <li><span class=\"kw-ci\">Opioïdes forts</span> : à ne pas prescrire (risque de mésusage).</li>\n        <li><span class=\"kw-alerte\">Pas de chirurgie</span> pour une rachialgie commune.</li>\n      </ul>\n      <p><strong>Formes chroniques</strong> — la <strong>rééducation active</strong> est le traitement principal : renforcement des muscles <span class=\"kw-clinique\">abdominaux</span>, <span class=\"kw-clinique\">spinaux</span> et <span class=\"kw-clinique\">quadriceps</span>, étirements, reconditionnement, <span class=\"kw-def\">exposition graduelle</span>. La <span class=\"kw-def\">neurostimulation électrique transcutanée (TENS)</span> est efficace sur la douleur. Des <span class=\"kw-ttt\">antidépresseurs</span> (IRSNA, tricycliques) ou <span class=\"kw-ttt\">gabapentinoïdes</span> peuvent être ajoutés en cas de composante dépressive ou de douleur neuropathique associée. <span class=\"kw-clinique\">Les</span> thérapies passives doivent être limitées.</p>","frequence":2},{"id":"94-14","rang":"A","rubrique":"Diagnostic positif","titre":"Diagnostic différentiel : connaître les causes extrarachidiennes des lombalgies","contenu":"<div class=\"callout callout-warn\"><strong>Piège classique.</strong> Évoquer une <strong>origine viscérale</strong> à une lombalgie devant l'<span class=\"kw-alerte\">absence de syndrome rachidien</span> (pas de contracture paravertébrale) et l'<span class=\"kw-alerte\">absence de reproduction des douleurs à la mobilisation du rachis</span>.</div>\n      <p><span class=\"kw-clinique\">Les</span> principales causes <strong>extrarachidiennes</strong> d'une douleur lombaire référée :</p>\n      <table >\n        <thead><tr><th>Appareil</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Vasculaire</span></td><td><strong>Anévrisme de l'aorte abdominale</strong> — tableau douloureux chronique, ou aigu lorsque <span class=\"kw-alerte\">fissuraire</span> (<span class=\"kw-clinique\">asymétrie</span> tensionnelle, abolition d'un pouls, souffle aortique).</td></tr>\n          <tr><td><span class=\"kw-etio\">Urologique</span></td><td>Pathologie des voies urinaires : <span class=\"kw-clinique\">colique néphrétique</span> (fébrile, anurique ou hyperalgique), hydronéphrose, tumeur.</td></tr>\n          <tr><td><span class=\"kw-etio\">Digestive</span></td><td>Tumeur digestive (gastrique, rectocolique ou pancréatique) ; pancréatite ; ulcère gastroduodénal.</td></tr>\n          <tr><td><span class=\"kw-etio\">Pelvien / rétropéritonéal</span></td><td>Tumeur pelvienne ; <span class=\"kw-clinique\">adénopathies</span> ou <span class=\"kw-def\">fibrose rétropéritonéale</span>.</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"94-15","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique devant une sacralgie","contenu":"<p><span class=\"kw-clinique\">Les</span> fiches sources ne comportent pas de section dédiée à la <span class=\"kw-def\">sacralgie</span>. Le contenu disponible le plus proche concerne le <span class=\"kw-def\">diagnostic différentiel</span> d'une <strong>fessalgie</strong> (douleur de la fesse), dont l'<span class=\"kw-etio\">origine sacro-iliaque</span> est une cause centrale.</p>\n      <table >\n        <thead><tr><th>Origine</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Radiculaire S1</span></td><td><span class=\"kw-clinique\">Irradiation</span> à la face <strong>postérieure</strong> de la cuisse, parfois jusqu'au pied ; souvent <span class=\"kw-clinique\">sciatique</span> sur hernie L5-S1 ; <span class=\"kw-clinique\">signe de Lasègue</span> positif.</td></tr>\n          <tr><td><span class=\"kw-etio\">Radiculaire L4</span></td><td><span class=\"kw-clinique\">Irradiation</span> à la face <strong>antérieure</strong> de la cuisse et au genou (<span class=\"kw-clinique\">cruralgie</span>, atteinte du nerf fémoral) — ce n'est pas une fessalgie ; <span class=\"kw-clinique\">signe du crural</span> positif.</td></tr>\n          <tr><td><span class=\"kw-etio\">Sacro-iliaque</span></td><td><span class=\"kw-clinique\">Fessalgie unilatérale</span>, accentuée par la station debout prolongée ; à rattacher aux <span class=\"kw-def\">spondylarthropathies</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Coxofémorale</span></td><td>Douleur irradiant en <strong>avant</strong> de la cuisse, pas dans la fesse ; douleur à la mobilisation de la hanche.</td></tr>\n          <tr><td><span class=\"kw-etio\">Tendinite du moyen fessier</span></td><td>Douleur <strong>latérale</strong> au grand trochanter, sans <span class=\"kw-clinique\">irradiation</span> ; pas de fessalgie vraie.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> La démarche diagnostique propre à la <strong>sacralgie</strong> (douleur du sacrum : fracture de fragilité du sacrum, sacro-iliite infectieuse ou <span class=\"kw-etio\">inflammatoire</span>, tumeur sacrée…) n'est pas détaillée dans <span class=\"kw-clinique\">les</span> fiches sources du dossier <code>94-rachialgie/</code>. Kevin enrichira ce paragraphe (Collège de MPR / rhumatologie, Lecofer).</div>","frequence":1},{"id":"94-16","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique devant une coccygodynie","contenu":"<div class=\"callout callout-warn\"><strong>À compléter.</strong> Aucun contenu correspondant à cet objectif n'a été trouvé dans <span class=\"kw-clinique\">les</span> fiches sources du dossier <code>94-rachialgie/</code>. Kevin enrichira ce paragraphe en cherchant la démarche diagnostique attendue devant une coccygodynie (Collège de MPR / rhumatologie, Lecofer, ou recherche ciblée).</div>\n      <!-- TODO Kevin : démarche diagnostique de la coccygodynie à rédiger -->","frequence":1}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.lecofer.org/item-cours-1-3-0.php","label":"Collège COFER — Lombalgies"}],"cards":[{"i":"00d1b387f7ce","n":94,"o":"94-1","u":"Définition","t":"Connaître les définitions des rachialgies : cervicalgie, dorsalgie, lombalgie","q":"Définissez topographiquement la cervicalgie, la dorsalgie et la lombalgie.","a":"<ul><li>La <strong>cervicalgie</strong> est une douleur du <strong>rachis cervical</strong>.</li><li>La <strong>dorsalgie</strong> est une douleur ressentie en regard du <strong>rachis thoracique</strong> (de T1 à T12).</li><li>La <strong>lombalgie</strong> est une douleur située entre la <strong>charnière thoracolombaire et le pli fessier inférieur</strong>.</li></ul>"},{"i":"2c2864189b1e","n":94,"o":"94-1","u":"Définition","t":"Connaître les définitions des rachialgies : cervicalgie, dorsalgie, lombalgie","q":"Quelles sont les définitions des différents types de lombalgie selon leur évolution ?","a":"<ul><li>La <strong>lombalgie commune</strong> est non spécifique, en rapport avec une origine discale, arthrosique ou musculaire.</li><li>La <strong>poussée aiguë de lombalgie</strong> désigne une douleur aiguë, avec ou sans fond douloureux préexistant.</li><li>La <strong>lombalgie chronique</strong> est une douleur évoluant depuis <strong>plus de 3 mois</strong>.</li><li>La <strong>lombalgie récidivante</strong> est une récidive dans les <strong>moins de 12 mois</strong>.</li><li>La <strong>lombalgie à risque de chronicité</strong> est caractérisée par la présence de <strong>drapeaux jaunes</strong>.</li></ul>"},{"i":"91310b1e4928","n":94,"o":"94-1","u":"Définition","t":"Connaître les définitions des rachialgies : cervicalgie, dorsalgie, lombalgie","q":"Quelle est la définition générale d'une rachialgie ?","a":"<p>La rachialgie est un <strong>symptôme</strong> caractérisé par une <strong>douleur du rachis</strong>, dont les étiologies sont variées.</p>"},{"i":"ec24a96531d6","n":94,"o":"94-1","u":"Définition","t":"Connaître les définitions des rachialgies : cervicalgie, dorsalgie, lombalgie","q":"Comment distingue-t-on une rachialgie commune d'une rachialgie secondaire ?","a":"<ul><li>La <strong>rachialgie commune</strong> est d'origine « dégénérative », souvent liée à une <strong>discopathie</strong> et/ou une atteinte articulaire postérieure.</li><li>La <strong>rachialgie secondaire</strong> relève d'étiologies spécifiques telles que <strong>tumorale, infectieuse, inflammatoire ou fracturaire</strong>, et doit être éliminée avant de retenir une rachialgie commune.</li></ul>"},{"i":"119a52411d7a","n":94,"o":"94-12","u":"Prise en charge","t":"Connaître les grands principes de prise en charge d’un sujet souffrant d’une rachialgie aiguë ou chronique","q":"En quoi consiste le programme de restauration fonctionnelle du rachis pour les formes chroniques de rachialgie ?","a":"Pour les formes chroniques de rachialgie, le programme de restauration fonctionnelle du rachis se déroule en hospitalisation, de manière multidisciplinaire (médecins MPR ou rhumatologue, kinésithérapeutes, ergothérapeutes, psychologues, assistants sociaux, diététiciens). Il vise principalement :\n<ul>\n  <li>Le <strong>reconditionnement à l'effort</strong>.</li>\n  <li>L'<strong>éducation thérapeutique</strong> du patient.</li>\n  <li>La <strong>réinsertion socioprofessionnelle</strong>.</li>\n</ul>\nLe bilan pré-rééducation inclut la mesure de la distance <strong>talon-fesse</strong> et des <strong>angles poplités</strong>, l'<strong>indice de Schöber</strong>, le score <strong>HAD</strong> (pour l'anxiété et la dépression), le questionnaire <strong>FABQ</strong> et un <strong>test de lever de charge (test de Pile)</strong>."},{"i":"50edcfe12bda","n":94,"o":"94-12","u":"Prise en charge","t":"Connaître les grands principes de prise en charge d’un sujet souffrant d’une rachialgie aiguë ou chronique","q":"Quels sont les principes généraux de prise en charge d'une rachialgie commune, qu'elle soit aiguë ou chronique ?","a":"Les principes généraux de prise en charge d'une rachialgie commune sont :\n<ul>\n  <li>Ne pas indiquer de chirurgie pour une rachialgie commune, même en cas de hernie discale visible à l'imagerie.</li>\n  <li>Traiter la symptomatologie du patient et non une image isolée.</li>\n  <li>Identifier l'origine de la rachialgie (discale, arthrosique, musculaire) pour orienter le traitement.</li>\n  <li>Éviter l'escalade thérapeutique (corticothérapie inefficace, opioïdes forts à risque de dépendance).</li>\n  <li>Privilégier une prise en charge <strong>active et précoce</strong>, en intégrant le contexte socioprofessionnel et psychologique pour prévenir la chronicisation.</li>\n  <li>Proscrire l'<strong>alitement</strong> et l'<strong>immobilisation prolongée</strong>.</li>\n  <li>Conseiller au patient de <strong>rester actif</strong> et de poursuivre ses activités quotidiennes et professionnelles si la douleur le permet.</li>\n</ul>"},{"i":"8eb80a65048e","n":94,"o":"94-12","u":"Prise en charge","t":"Connaître les grands principes de prise en charge d’un sujet souffrant d’une rachialgie aiguë ou chronique","q":"Quelle est l'approche pluridisciplinaire recommandée pour la prise en charge d'une rachialgie ?","a":"La prise en charge pluridisciplinaire d'une rachialgie implique différents intervenants selon la ligne et la sévérité :\n<ul>\n  <li>Le <strong>Médecin généraliste</strong> est en 1ʳᵉ ligne pour les rachialgies sans signe d'alerte ni de gravité.</li>\n  <li>Le <strong>Rhumatologue</strong> intervient en 2ᵉ ligne, pour le diagnostic et les formes rebelles.</li>\n  <li>L'<strong>Imageur</strong> (radiologue) est sollicité en 3ᵉ ligne pour les formes rebelles, avec signes d'alerte ou de gravité.</li>\n  <li>Le <strong>Rééducateur</strong> et les <strong>Kinésithérapeutes</strong> prennent en charge les formes rebelles ou en voie de chronicisation.</li>\n  <li>Le <strong>Chirurgien</strong> intervient uniquement en cas de complications neurologiques ou de résistance au traitement médical.</li>\n</ul>"},{"i":"7846314e52e1","n":94,"o":"94-14","u":"Diagnostic positif","t":"Diagnostic différentiel : connaître les causes extrarachidiennes des lombalgies","q":"Quelles sont les causes digestives ou pelviennes/rétropéritonéales de lombalgie référée ?","a":"<ul><li><strong>Tumeur digestive</strong> (gastrique, rectocolique ou pancréatique)</li><li><strong>Pancréatite</strong></li><li><strong>Ulcère gastroduodénal</strong></li><li><strong>Tumeur pelvienne</strong></li><li><strong>Adénopathies rétropéritonéales</strong></li><li><strong>Fibrose rétropéritonéale</strong></li></ul>"},{"i":"822b0eacc389","n":94,"o":"94-14","u":"Diagnostic positif","t":"Diagnostic différentiel : connaître les causes extrarachidiennes des lombalgies","q":"Quels sont les signes d'alerte cliniques permettant d'évoquer une origine extrarachidienne à une lombalgie plutôt qu'une origine rachidienne ?","a":"<p>Devant une lombalgie, il faut évoquer une origine extrarachidienne en cas d'<strong>absence de syndrome rachidien</strong> (c'est-à-dire pas de contracture paravertébrale) et d'<strong>absence de reproduction des douleurs à la mobilisation du rachis</strong>.</p>"},{"i":"875f2ed61fa7","n":94,"o":"94-14","u":"Diagnostic positif","t":"Diagnostic différentiel : connaître les causes extrarachidiennes des lombalgies","q":"Quelles sont les causes vasculaires extrarachidiennes de lombalgie référée ?","a":"<ul><li><strong>Anévrisme de l'aorte abdominale</strong> : la douleur peut être chronique, ou aiguë en cas de fissuration. Dans ce dernier cas, des signes d'alerte sont une <strong>asymétrie tensionnelle</strong>, l'<strong>abolition d'un pouls</strong> ou un <strong>souffle aortique</strong>.</li></ul>"},{"i":"dd9bd5cc99fc","n":94,"o":"94-14","u":"Diagnostic positif","t":"Diagnostic différentiel : connaître les causes extrarachidiennes des lombalgies","q":"Quelles sont les causes urologiques de lombalgie référée ?","a":"<ul><li><strong>Colique néphrétique</strong> (notamment si fébrile, anurique ou hyperalgique)</li><li><strong>Hydronéphrose</strong></li><li><strong>Tumeur des voies urinaires</strong></li></ul>"},{"i":"0db6d09ccbd1","n":94,"o":"94-3","u":"Diagnostic positif","t":"Savoir interroger un patient et l’examiner devant une rachialgie","q":"Quels sont les différents types de drapeaux à considérer lors de l'évaluation d'une rachialgie à l'interrogatoire et à l'examen clinique ?","a":"<p>L'évaluation d'une rachialgie vise à classer la douleur selon différents drapeaux :</p><ul><li>Les <strong>drapeaux verts</strong> : orientent vers une cause mécanique.</li><li>Les <strong>drapeaux jaunes et noirs</strong> : indiquent un risque de chronicité.</li><li>Les <strong>drapeaux rouges</strong> : signalent une cause secondaire grave.</li></ul>"},{"i":"983a4faa116b","n":94,"o":"94-3","u":"Diagnostic positif","t":"Savoir interroger un patient et l’examiner devant une rachialgie","q":"Comment évaluer la statique et la mobilité rachidienne lors de l'examen clinique d'une rachialgie ?","a":"<p>Lors de l'examen clinique d'une rachialgie, la statique et la mobilité rachidienne s'évaluent ainsi :</p><ul><li><strong>Statique rachidienne</strong> : patient debout, de profil et de dos, rechercher une hyperlordose lombaire, une hypercyphose, une scoliose et une gibbosité en antéflexion.</li><li><strong>Mobilités</strong> : évaluer la flexion-extension, les latéroflexions et les rotations. Une raideur est attendue en phase aiguë, des mobilités subnormales dans la chronicité.</li><li><strong>Indices spécifiques</strong> : le <strong>test de Schöber</strong> (normal si augmentation > <strong>13 cm</strong>) et la <strong>distance main-sol</strong>.</li><li>Enfin, rechercher un <strong>syndrome cellulo-myalgique</strong> (hyperesthésie au palper-rouler) orientant vers une arthrose des zygapophyses.</li></ul>"},{"i":"e78b71b50866","n":94,"o":"94-3","u":"Diagnostic positif","t":"Savoir interroger un patient et l’examiner devant une rachialgie","q":"Lors de l'interrogatoire d'une rachialgie, quels sont les éléments clés à rechercher pour caractériser la douleur ?","a":"<p>Pour caractériser une rachialgie, les éléments clés à rechercher lors de l'interrogatoire sont :</p><ul><li>Les <strong>circonstances de survenue</strong> (effort, traumatisme, posture prolongée).</li><li>Le <strong>siège et les irradiations</strong> (typique lombaire basse, lombofessière).</li><li>Le <strong>rythme</strong> (mécanique ou inflammatoire).</li><li>Le <strong>caractère impulsif à la toux, la défécation, l'éternuement</strong>, orientant vers une origine discale.</li><li>Le mode évolutif et les antécédents de rachialgies.</li><li>La recherche de <strong>signes généraux</strong>.</li></ul>"},{"i":"f5c853087496","n":94,"o":"94-3","u":"Diagnostic positif","t":"Savoir interroger un patient et l’examiner devant une rachialgie","q":"Quel est l'intérêt du signe de Lasègue dans l'examen clinique d'une rachialgie ?","a":"<p>Le signe de Lasègue est important dans l'examen clinique d'une rachialgie pour distinguer une douleur lombaire pure d'une radiculalgie :</p><ul><li>Un <strong>Lasègue lombaire</strong> (douleur lombaire pure, sans douleur radiculaire dans le membre inférieur) est possible dans les rachialgies et <strong>ne signe pas une atteinte radiculaire</strong>.</li><li>C'est le <strong>Lasègue radiculaire</strong> qui est évocateur d'une atteinte radiculaire et donc d'une radiculalgie.</li></ul>"},{"i":"5c13b1c5d00b","n":94,"o":"94-6","u":"Examens complémentaires","t":"Savoir demander à bon escient une imagerie devant une rachialgie","q":"Quand faut-il envisager une IRM pour une lombalgie ou une névralgie cervico-brachiale ?","a":"<ul><li>Pour une <strong>lombalgie</strong> : Une IRM est indiquée en cas de <strong>lombalgie chronique > 3 mois</strong> ou en présence de <strong>drapeaux rouges</strong>.</li><li>Pour une <strong>lombosciatique</strong> : L'IRM est l'examen à privilégier, surtout si la douleur <strong>persiste > 8 semaines</strong> malgré un traitement bien conduit, si elle est <strong>invalidante</strong>, ou si une <strong>chirurgie/infiltration</strong> est prévue, ou chez un <strong>adolescent</strong> ou un <strong>patient > 65 ans</strong>. En cas de suspicion de drapeau rouge, l'IRM est d'office.</li><li>Pour une <strong>névralgie cervico-brachiale</strong> : L'IRM doit être réalisée <strong>directement</strong> si la douleur <strong>persiste > 4-6 semaines</strong> malgré le traitement, ou en cas de <strong>résistance au traitement</strong> ou de <strong>drapeaux rouges</strong>.</li></ul>"},{"i":"6054730b3efb","n":94,"o":"94-6","u":"Examens complémentaires","t":"Savoir demander à bon escient une imagerie devant une rachialgie","q":"Qu'est-ce que la classification de Modic en IRM et quel est son intérêt clinique pour la rachialgie ?","a":"<p>La classification de Modic décrit les modifications des plateaux vertébraux, visibles en IRM, au cours de la dégénérescence discale lombaire :</p><ul><li><strong>Modic 1</strong> : Correspond à un <strong>œdème</strong> des plateaux vertébraux (hypoT1, hyperT2, hyperSTIR) et est souvent <strong>douloureux</strong>, corrélé à l'acutisation d'une lombalgie chronique.</li><li><strong>Modic 2</strong> : Caractérise une <strong>involution graisseuse</strong> (hyperT1, hyperT2, hypoSTIR).</li><li><strong>Modic 3</strong> : Traduit une <strong>ostéosclérose</strong> (hypoT1, hypoT2).</li></ul><p>Le Modic 1 est particulièrement important à retenir, car il peut révéler une <strong>discopathie destructrice rapide</strong>.</p>"},{"i":"92df7c5e2fa2","n":94,"o":"94-6","u":"Examens complémentaires","t":"Savoir demander à bon escient une imagerie devant une rachialgie","q":"Dans quel contexte général doit-on demander une imagerie pour une rachialgie ?","a":"<p>L'imagerie d'une rachialgie est indiquée en fonction de sa <strong>localisation</strong>, sa <strong>durée</strong>, et la <strong>réponse au traitement</strong>. Elle n'est <strong>jamais systématique en phase aiguë</strong>, sauf en présence de <strong>drapeaux rouges</strong>.</p>"},{"i":"b611233c2969","n":94,"o":"94-6","u":"Examens complémentaires","t":"Savoir demander à bon escient une imagerie devant une rachialgie","q":"Quelle est la place de l'IRM et du scanner dans l'exploration des rachialgies ?","a":"<ul><li>L'<strong>IRM</strong> est l'examen de <strong>référence</strong> en cas de <strong>suspicion neurologique</strong> ou de <strong>résistance au traitement</strong>. Elle est indiquée <strong>en urgence</strong> en présence de <strong>drapeaux rouges</strong>.</li><li>Le <strong>scanner (TDM)</strong> est <strong>moins performant</strong> que l'IRM pour l'exploration du rachis et est plutôt utilisé en <strong>complément</strong> de l'IRM dans certaines situations.</li><li>La <strong>radiographie</strong> reste utile pour évaluer les <strong>déformations</strong> et la <strong>statique rachidienne</strong>.</li></ul>"},{"i":"bc03c4f18997","n":94,"o":"94-6","u":"Examens complémentaires","t":"Savoir demander à bon escient une imagerie devant une rachialgie","q":"Une imagerie anormale d'une rachialgie signifie-t-elle forcément que le patient est symptomatique ?","a":"<p>Non, il n'existe <strong>aucun parallélisme</strong> entre l'imagerie et la clinique. Un rachis présentant des signes de dégénérescence importants à l'imagerie peut être <strong>asymptomatique</strong>. L'imagerie peut par ailleurs avoir un <strong>effet nocebo</strong>.</p>"},{"i":"ed8dbb8e6f99","n":94,"o":"94-6","u":"Examens complémentaires","t":"Savoir demander à bon escient une imagerie devant une rachialgie","q":"Quelle est la stratégie d'imagerie de première intention pour une cervicalgie et une lombalgie non spécifiques ?","a":"<ul><li>Pour une <strong>cervicalgie sans drapeau rouge</strong> : une radiographie cervicale (face, profil, trois quarts, C1-C2 si douleurs hautes, dynamiques si ATCD traumatiques) est indiquée si la douleur <strong>persiste plus de 4-6 semaines</strong> malgré le traitement. Elle est inutile pour un simple torticolis ou une cervicalgie connue récidivante.</li><li>Pour une <strong>lombalgie sans drapeau rouge</strong> : une radiographie lombaire (face, profil, bassin de face, dynamiques si ATCD traumatiques) est indiquée si la douleur <strong>persiste plus de 6-8 semaines</strong> malgré le traitement. Elle est inutile pour un simple lumbago.</li></ul>"},{"i":"463f9b5f64a5","n":94,"o":"94-7","u":"Identifier une urgence","t":"Connaître les arguments en faveur d’une rachialgie secondaire conduisant à la pratique d’examens complémentaires (IRM)","q":"Quels sont les 'drapeaux rouges' en relation avec le terrain du patient qui doivent faire suspecter une rachialgie secondaire et conduire à une IRM ?","a":"<p>Devant une rachialgie, les 'drapeaux rouges' liés au <strong>terrain</strong> du patient et faisant craindre une cause secondaire sont :</p><ul><li>Un âge d'apparition <strong>inférieur à 20 ans ou supérieur à 55 ans</strong>.</li><li>Des <strong>antécédents</strong> tumoraux, infectieux ou de maladie inflammatoire rhumatismale.</li><li>Une <strong>immunosuppression</strong>.</li><li>Une <strong>toxicomanie</strong>.</li><li>Une <strong>corticothérapie prolongée</strong>.</li></ul>"},{"i":"5a506e7f9f0f","n":94,"o":"94-7","u":"Identifier une urgence","t":"Connaître les arguments en faveur d’une rachialgie secondaire conduisant à la pratique d’examens complémentaires (IRM)","q":"Dans quel contexte doit-on évoquer une dissection artérielle devant des cervicalgies, justifiant des examens complémentaires ?","a":"<p>Une <strong>dissection artérielle</strong> doit être évoquée devant des cervicalgies si elles sont <strong>inhabituelles et persistantes</strong>, associées à des <strong>céphalées inhabituelles</strong> et/ou des <strong>signes neurologiques focaux</strong>. Ce risque est accru en présence d'antécédents de maladies prédisposantes telles que le syndrome d'<strong>Ehlers-Danlos</strong>, de <strong>Marfan</strong>, l'<strong>ostéogenèse imparfaite</strong> ou la <strong>dysplasie fibromusculaire</strong>.</p>"},{"i":"67dd8ed7a19c","n":94,"o":"94-7","u":"Identifier une urgence","t":"Connaître les arguments en faveur d’une rachialgie secondaire conduisant à la pratique d’examens complémentaires (IRM)","q":"Quelles caractéristiques de la douleur rachidienne évoquent une rachialgie secondaire et nécessitent des examens complémentaires comme l'IRM ?","a":"<p>Les caractéristiques de la douleur rachidienne qui doivent faire suspecter une rachialgie secondaire sont :</p><ul><li>Un début <strong>insidieux</strong> et une évolution <strong>progressivement croissante</strong>.</li><li>Des <strong>douleurs nocturnes inflammatoires</strong> (insomniantes) ou une <strong>douleur de repos</strong>.</li><li>Un caractère <strong>rebelle aux traitements symptomatiques</strong>.</li><li>Des <strong>localisations multiples ou atypiques</strong>.</li></ul>"},{"i":"807c4dfc930c","n":94,"o":"94-7","u":"Identifier une urgence","t":"Connaître les arguments en faveur d’une rachialgie secondaire conduisant à la pratique d’examens complémentaires (IRM)","q":"Quels signes associés à une rachialgie orientent vers une cause secondaire grave et impliquent la réalisation d'une IRM ?","a":"<p>Les signes associés à une rachialgie qui doivent alerter et faire suspecter une cause secondaire sont :</p><ul><li>Une <strong>fièvre</strong>.</li><li>Une <strong>altération de l'état général</strong> (sueurs nocturnes, perte de poids inexpliquée).</li><li>Un <strong>déficit neurologique</strong> : une atteinte radiculaire (déficit moteur radiculaire ± névralgie cervico-brachiale) ou une atteinte médullaire (déficit moteur/sensitif sous-lésionnel, signes d'irritation pyramidale, troubles vésicosphinctériens).</li><li>Des <strong>adénopathies</strong>.</li><li>Une <strong>déformation structurale importante</strong> de la colonne.</li><li>Une <strong>douleur thoracique</strong> (pour les rachialgies dorsales).</li><li>Un <strong>contexte traumatique important</strong> (chute de hauteur) ou des antécédents de chirurgie du rachis avec modification de la symptomatologie.</li></ul>"},{"i":"db363357c04f","n":94,"o":"94-7","u":"Identifier une urgence","t":"Connaître les arguments en faveur d’une rachialgie secondaire conduisant à la pratique d’examens complémentaires (IRM)","q":"Une radiculalgie isolée chez un patient doit-elle faire systématiquement suspecter une rachialgie secondaire grave et justifier une IRM ?","a":"<p><strong>Non, une radiculalgie à elle seule n'est pas un argument suffisant</strong> pour affirmer une rachialgie secondaire grave. Il faut impérativement un <strong>déficit neurologique associé</strong> (moteur, sensitif, troubles sphinctériens) pour considérer ce signe comme un 'drapeau rouge' justifiant une investigation approfondie (IRM).</p>"},{"i":"04d738f53d1c","n":94,"o":"94-9","u":"Étiologies","t":"Connaître les principales étiologies d’une rachialgie secondaire","q":"Quelle est la principale étiologie osseuse fragilisante d'une rachialgie secondaire ?","a":"<p>Il s'agit de la <strong>fracture vertébrale ostéoporotique</strong>, survenant dans un contexte de fragilité osseuse.</p>"},{"i":"44362bfaeec6","n":94,"o":"94-9","u":"Étiologies","t":"Connaître les principales étiologies d’une rachialgie secondaire","q":"Quelles sont les étiologies tumorales principales à évoquer devant une rachialgie secondaire ?","a":"<ul><li>Les <strong>métastases osseuses</strong> (particulièrement des lésions <strong>lytiques</strong>).</li><li>Une localisation <strong>myélomateuse</strong>.</li><li>Une <strong>tumeur primitive vertébrale</strong>.</li></ul>"},{"i":"45841753a0c4","n":94,"o":"94-9","u":"Étiologies","t":"Connaître les principales étiologies d’une rachialgie secondaire","q":"Quelle est la définition d'une rachialgie secondaire ?","a":"<p>Une rachialgie secondaire relève d'une <strong>pathologie non mécanique</strong>.</p>"},{"i":"9d2cb05692f6","n":94,"o":"94-9","u":"Étiologies","t":"Connaître les principales étiologies d’une rachialgie secondaire","q":"Quelles sont les étiologies infectieuses et inflammatoires principales d'une rachialgie secondaire ?","a":"<ul><li><strong>Infectieuses</strong> : la <strong>spondylodiscite</strong> (la spondylite est plus rare).</li><li><strong>Inflammatoires</strong> : les <strong>spondylarthrites</strong> (dont le rhumatisme psoriasique), la <strong>polyarthrite rhumatoïde</strong> (avec une atteinte spécifique de <strong>C1-C2</strong>), la <strong>chondrocalcinose</strong>, et le <strong>rhumatisme à apatite</strong>.</li></ul>"},{"i":"af699e44222a","n":94,"o":"94-9","u":"Étiologies","t":"Connaître les principales étiologies d’une rachialgie secondaire","q":"Quels examens complémentaires sont justifiés devant la suspicion d'une rachialgie secondaire ?","a":"<ul><li>Une <strong>IRM</strong> (Imagerie par Résonance Magnétique).</li><li>Un <strong>bilan biologique</strong> comprenant la <strong>CRP/VS</strong> (Marqueurs de l'inflammation), une <strong>électrophorèse des protides</strong>, et une <strong>calcémie</strong>.</li></ul>"}]};